                @Move.performed -= instance.OnMove;
                @Move.canceled -= instance.OnMove;
                @Jump.started -= instance.OnJump;
                @Jump.performed -= instance.OnJump;
                @Jump.canceled -= instance.OnJump;
                @Dash.started -= instance.OnDash;
                @Dash.performed -= instance.OnDash;
                @Dash.canceled -= instance.OnDash;
                @L.started -= instance.OnL;
                @L.performed -= instance.OnL;
                @L.canceled -= instance.OnL;
                @M.started -= instance.OnM;
                @M.performed -= instance.OnM;
                @M.canceled -= instance.OnM;
                @H.started -= instance.OnH;
                @H.performed -= instance.OnH;
                @H.canceled -= instance.OnH;
                @Super1.started -= instance.OnSuper1;
                @Super1.performed -= instance.OnSuper1;
                @Super1.canceled -= instance.OnSuper1;
                @Super2.started -= instance.OnSuper2;
                @Super2.performed -= instance.OnSuper2;
                @Super2.canceled -= instance.OnSuper2;
                @Rage.started -= instance.OnRage;
                @Rage.performed -= instance.OnRage;
                @Rage.canceled -= instance.OnRage;
